import csv
with open('outputs/t06_stop_service_intensity.csv', 'r', encoding='utf-8') as f:
    reader = csv.reader(f)
    for i, row in enumerate(reader):
        # Check if row has 8 fields
        if len(row) != 8:
            print(f'ERROR: Row {i} has {len(row)} fields instead of 8')
            print(row)
        # Check if any field with comma is properly quoted
        for j, field in enumerate(row):
            if ',' in field and not field.startswith('\"'):
                print(f'WARNING: Row {i}, field {j} has comma but not quoted: {field}')
print('CSV validation complete')
""}
